double predictVectorRatio(const std::array<double,15>& features) {
  float x[15]; for (int i=0;i<15;++i) x[i]=static_cast<float>(features[i]);
  double sum=0; for (int root:roots) { int i=root; while (nodes[i].feature>=0) {
    const auto& n=nodes[i]; i=x[n.feature]<=n.value?n.left:n.right; } sum+=nodes[i].value; }
  return std::exp(sum/(sizeof(roots)/sizeof(roots[0])));
}
